const scoreSpan = document.getElementById('score');
const restartBtn = document.getElementById('restartBtn');

const PLAYER_SIZE = 40;
const PLAYER_SPEED = 4; // מהירות אופקית
const GRAVITY = 0.6;
const JUMP_STRENGTH = -12;
const MAX_LEVEL = 50;

let level = 1;
let score = 0;
let obstacles = []; // מכשולים רגילים (קוביות)
let cones = []; // קונוסים (דורשים קפיצה)
let gameOver = false;

/* ==================== השחקן ==================== */
const player = {
 x: 80,
 y: canvas.height - PLAYER_SIZE,
 width: PLAYER_SIZE,
 height: PLAYER_SIZE,
 vy: 0,
 vx: 0,
 onGround: true,
 draw(){
 // כובע שחור
 ctx.fillStyle = '#000';
 ctx.fillRect(this.x, this.y-10, this.width, 10);
 // פאות לבנות
 ctx.fillStyle = '#fff';
 ctx.fillRect(this.x+5, this.y-20, this.width-10, 10);
 // חולצה צהובה (גוף)
 ctx.fillStyle = var(--player);
 ctx.fillRect(this.x, this.y, this.width, this.height);
 },
 update(){
 // תנועה אופקית
 this.x += this.vx;
 // גבולות המסך
 if(this.x < 0) this.x = 0;
 if(this.x + this.width > canvas.width) this.x = canvas.width - this.width;

 // פיזיקת קפיצה
 this.vy += GRAVITY;
 this.y += this.vy;
 if(this.y + this.height >= canvas.height){
 this.y = canvas.height - this.height;
 this.vy = 0;
 this.onGround = true;
 }else{
 this.onGround = false;
 }
 },
 jump(){
 if(this.onGround){
 this.vy = JUMP_STRENGTH;
 this.onGround = false;
 }
 },
 reset(){
 this.x = 80;
 this.y = canvas.height - PLAYER_SIZE;
 this.vx = 0;
 this.vy = 0;
 this.onGround = true;
 }
};

/* ==================== יצירת מכשול רגיל ==================== */
function createObstacle(){
 const minSize = 20;
 const maxSize = 60;
 const size = Math.max(minSize, maxSize - level*0.8);
 const speed = 2 + level*0.1;
 const gap = Math.max(150, 300 - level*3);
 const obstacle = {
 x: canvas.width + Math.random()*gap,
 y: canvas.height - size,
 width: size,
 height: size,
 speed: speed,
 draw(){ ctx.fillStyle = var(--obstacle); ctx.fillRect(this.x,this.y,this.width,this.height); },
 update(){ this.x -= this.speed; }
 };
 obstacles.push(obstacle);
}

/* ==================== יצירת קונוס (דורש קפיצה) ==================== */
function createCone(){
 const size = 30; // קוטר קונוס קבוע
 const speed = 2 + level*0.1;
 const gap = Math.max(180, 320 - level*3);
 const cone = {
 x: canvas.width + Math.random()*gap,
 y: canvas.height - size,
 width: size,
 height: size,
 speed: speed,
 draw(){ ctx.fillStyle = var(--cone); ctx.beginPath(); ctx.moveTo(this.x, this.y+this.height);
 ctx.lineTo(this.x+this.width/2, this.y);
 ctx.lineTo(this.x+this.width, this.y+this.height);
 ctx.closePath(); ctx.fill(); },
 update(){ this.x -= this.speed; }
 };
 cones.push(cone);
}

/* ==================== בדיקת התנגשות ==================== */
function checkCollision(a,b){
 return !(a.x > b.x+b.width ||
 a.x+a.width < b.x ||
 a.y > b.y+b.height ||
 a.y+a.height < b.y);
}

/* ==================== מעבר שלב ==================== */
function nextLevel(){
 if(level >= MAX_LEVEL){
 alert(`כל הכבוד! סיימת את כל ${MAX_LEVEL} השלבים עם ניקוד ${score}`);
 gameOver = true;
 restartBtn.style.display = 'inline-block';
 return;
 }
 level++;
 levelSpan.textContent = level;
}

/* ==================== לולאת המשחק ==================== */
let frameCount = 0;
function gameLoop(){
 if(gameOver) return;

 ctx.clearRect(0,0,canvas.width,canvas.height);

 // רקע המסלול
 ctx.fillStyle = var(--track);
 ctx.fillRect(0,canvas.height-10,canvas.width,10);

 // עדכון שחקן
 player.update();
 player.draw();

 // יצירת מכשולים – קצב תלוי ברמה
 if(frameCount % Math.max(80 - level*1.2,30) === 0){
 createObstacle();
 // כל 3 שלבים מוסיפים קונוס
 if(level % 3 === 0) createCone();
 }

 // עדכון/שרטוט מכשולים רגילים
 for(let i=obstacles.length-1;i>=0;i--){
 const o = obstacles[i];
 o.update();
 o.draw();
 if(checkCollision(player,o)){
 gameOver = true;
 alert(`הפסדת! נגעת במכשול. ניקוד: ${score}`);
 restartBtn.style.display='inline-block';
 }
 if(o.x + o.width < 0){
 obstacles.splice(i,1);
 score += 10;
 scoreSpan.textContent = score;
 }
 }

 // עדכון/שרטוט קונוסים
 for(let i=cones.length-1;i>=0;i--){
 const c = cones[i];
 c.update();
 c.draw();
 // קונוס נחשב להתנגשות רק אם השחקן לא קפץ מעליו
 if(checkCollision(player,c)){
 // אם השחקן נמצא במצב קפיצה (vy < 0) – הוא "קפץ" מעל הקונוס
 if(player.vy >= 0){ // נגיעה מהצד או מהאדמה
 gameOver = true;
 alert(`הפסדת! נגעת בקונוס. ניקוד: ${score}`);
 restartBtn.style.display='inline-block';
 }
 }
 if(c.x + c.width < 0){
 cones.splice(i,1);
 score += 15; // ניקוד גבוה יותר על קונוס שעבר
 scoreSpan.textContent = score;
 }
 }

 // מעבר לשלב הבא כששחקן מגיע לקצה הימני
 if(player.x + player.width > canvas.width - 100){
 player.x = 80;
 nextLevel();
 obstacles = [];
 cones = [];
 }

 frameCount++;
 requestAnimationFrame(gameLoop);
}

/* ==================== שליטה במקשי החצים ==================== */
const keys = { ArrowLeft:false, ArrowRight:false, ArrowUp:false };
document.addEventListener('keydown',e=>{
 if(e.code in keys){
 keys[e.code]=true;
 if(e.code==='ArrowUp') player.jump();
 }
});
document.addEventListener('keyup',e=>{
 if(e.code in keys) keys[e.code]=false;
});
/* תנועה אופקית מתעדכנת בכל פריים */
function handleHorizontalMovement(){
 if(keys.ArrowLeft) player.vx = -PLAYER_SPEED;
 else if(keys.ArrowRight) player.vx = PLAYER_SPEED;
 else player.vx = 0;
}

/* ==================== הפעלה ראשונית ==================== */
restartBtn.addEventListener('click',()=>{
 level=1; score=0;
 levelSpan.textContent=level;
 scoreSpan.textContent=score;
 obstacles=[]; cones=[];
 player.reset();
 gameOver=false;
 restartBtn.style.display='none';
 frameCount=0;
 gameLoop();
});

/* לולאה עם טיפול בתנועה אופקית */
function mainLoop(){
 handleHorizontalMovement();
 gameLoop();
}
mainLoop(); // מתחיל את המשחק
</script>
</body>
</html>
```

### מה השתנה
- **שליטה במקשי החצים**: 
 - `←` – תנועה שמאלה. 
 - `→` – תנועה ימינה. 
 - `↑` – קפיצה (אותו קפיצה כמו לפני). 
- **מכשול נוסף – קונוס כחול**: קונוס דורש קפיצה מעליו; אם השחקן נוגע בקונוס ללא קפיצה, המשחק נגמר. קונוסים מופיעים כל שלושה שלבים ומעניקים ניקוד גבוה יותר. 
- **הפרדת לולאות**: `handleHorizontalMovement` מתעדכן בכל פריים כדי לשמור על תנועה חלקה. 
- **ניקוד משופר**: קונוס מוסיף 15 נקודות במקום 10. 

הקוד מוכן לשימוש – פתח את הקובץ בדפדפן ותהנה ממשחק משופר! 🎮✨

**📋 תכנון:** 

1. **מבנה קבצים** – קובץ `index.html` שמטמיע את ה‑HTML, קובץ `styles.css` לעיצוב ו‑`app.js` לתפעול הלוגיקה. 
2. **HTML** – מבנה דף מינימלי עם כותרת, שדה קלט להוספת משימה, רשימת משימות ריקה, ואלמנטים למצב טעינה/שגיאה/ריק. 
3. **CSS** – 
 - משתני CSS (`--primary`, `--bg`, `--radius`…) לניהול תמות. 
 - עיצוב מודרני עם גרדיאנטים, צללים, אנימציות עדינות (fade‑in, hover scale). 
 - רספונסיביות (breakpoints : 375 px, 768 px, 1024 px, 1440 px). 
 - נגישות: תגים סמנטיים, ARIA, מצבי פוקוס ברורים. 
4. **JS** – 
 - מודול ES2023 עם IIFE כדי למנוע זיהום גלובלי. 
 - פונקציות: `addTask`, `toggleTask`, `deleteTask`, `renderTasks`, `showMessage`. 
 - אימות קלט (לא לקבל מחרוזות ריקות או רק רווחים). 
 - טיפול בשגיאות עם הודעות מודאליות. 
