### `app.js`
```js
// app.js – מודול ES2023
(() => {
 'use strict';

 // בחירת אלמנטים
 const taskInput = document.getElementById('task-input');
 const addBtn = document.getElementById('add-btn');
 const taskList = document.getElementById('task-list');
 const statusEl = document.getElementById('status');

 // מפתח אחסון
 const STORAGE_KEY = 'todo-tasks';

 // מבנה משימה
 /**
 * @typedef {{ id: string, text: string, completed: boolean }} Task
 */

 /** @type {Task[]} */
 let tasks = [];

 // ---------- פונקציות עזר ----------
 const showMessage = (msg, type = 'info') => {
 statusEl.textContent = msg;
 statusEl.className = `status ${type}`;
 statusEl.classList.remove('hidden');
 // מחיקה אוטומטית אחרי 3 שניות (ל‑info ו‑error)
 if (type !== 'loading') {
 setTimeout(() => statusEl.classList.add('hidden'), 3000);
 }
 };

 const saveTasks = () => {
 try {
 localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
 } catch (e) {
 showMessage('שגיאה בשמירת המשימות במכשיר שלך.', 'error');
 }
 };

 const loadTasks = () => {
 showMessage('טוען משימות...', 'loading');
 try {
 const raw = localStorage.getItem(STORAGE_KEY);
 tasks = raw ? JSON.parse(raw) : [];
 renderTasks();
 if (tasks.length === 0) showMessage('אין משימות. תתחיל להוסיף!', 'empty');
 else statusEl.classList.add('hidden');
 } catch (e) {
 showMessage('שגיאה בטעינת המשימות.', 'error');
 tasks = [];
 }
 };

 const createTaskElement = (task) => {
 const li = document.createElement('li');
 li.className = `task-item${task.completed ? ' completed' : ''}`;
 li.setAttribute('data-id', task.id);

 const checkbox = document.createElement('input');
 checkbox.type = 'checkbox';
 checkbox.checked = task.completed;
 checkbox.setAttribute('aria-label', 'סמן כבוצע');
 checkbox.addEventListener('change', () => toggleTask(task.id));

 const span = document.createElement('span');
 span.className = 'task-text';
 span.textContent = task.text;

 const actions = document.createElement('div');
 actions.className = 'task-actions';

 const delBtn = document.createElement('button');
 delBtn.innerHTML = '🗑️';
 delBtn.setAttribute('aria-label', 'מחק משימה');
 delBtn.addEventListener('click', () => deleteTask(task.id));

 actions.appendChild(delBtn);
 li.append(checkbox, span, actions);
 return li;
 };

 const renderTasks = () => {
 taskList.innerHTML = '';
 if (tasks.length === 0) {
 taskList.innerHTML = '<li class="empty">אין משימות להצגה.</li>';
 return;
 }
 const fragment = document.createDocumentFragment();
 tasks.forEach(task => fragment.appendChild(createTaskElement(task)));
 taskList.appendChild(fragment);
 };

 // ---------- לוגיקה עסקית ----------
 const addTask = () => {
 const rawText = taskInput.value.trim();
 if (!rawText) {
 showMessage('המשימה לא יכולה להיות ריקה.', 'error');
 return;
 }

 const newTask = {
 id: crypto.randomUUID(),
 text: rawText,
 completed: false
 };
 tasks.unshift(newTask); // מוסיף לראש הרשימה
 saveTasks();
 renderTasks();
 taskInput.value = '';
 showMessage('המשימה נוספה בהצלחה!', 'info');
 };

 const toggleTask = (id) => {
 const task = tasks.find(t => t.id === id);
 if (!task) return;
 task.completed = !task.completed;
 saveTasks();
 renderTasks();
 };

 const deleteTask = (id) => {
 tasks = tasks.filter(t => t.id !== id);
 saveTasks();
 renderTasks();
 showMessage('המשימה נמחקה.', 'info');
 };

 // ---------- אירועי UI ----------
 addBtn.addEventListener('click', addTask);
 taskInput.addEventListener('keypress', (e) => {
 if (e.key === 'Enter') addTask();
 });

 // ---------- אתחול ----------
 document.addEventListener('DOMContentLoaded', loadTasks);
})();
