}
@media (min-width: 768px) {
 .board { gap: 1rem; }
}
@media (min-width: 1024px) {
 .board { gap: 1.2rem; }
}

/* קלף */
.card {
 width: var(--card-size);
 height: var(--card-size);
 perspective: 800px;
